-- Prueba humana confirmada el 16/10/2026. Sólo contenido editorial; no repite el corte.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('corte-caja-sobrante-1',$texto$Cerrar caja con un sobrante de $1 justificado$texto$,'Finanzas',$texto$Preparar una caja aislada con $1,150, comprobar rechazo de un conteo de $1,151 sin justificación, cerrar con motivo y verificar que no se cree un ingreso automático.$texto$,$texto$Usuario administrativo persistido autorizado, institución y plantel accesibles, cuenta de prueba tipo CAJA activa en MXN y sin operaciones concurrentes. El usuario de recuperación no puede operar cortes. No repetir el ensayo ya terminado: consultar su detalle. Git no transporta cajas ni cortes de otra computadora. Cancelar modal y exportar Excel son controles adicionales recomendados, no aceptaciones humanas atribuidas a este caso.$texto$,$texto$Caso confirmado en CAJA-SOBRANTE-TEST: cuenta inicial $1,150.00, corte inicial/esperado $1,150.00, declarado $1,151.00, diferencia +$1.00, cero movimientos, ingresos/egresos $0.00 y cuenta conserva $1,150.00. El intento sin justificación fue rechazado; con justificación se cerró. En esta BD fue corte1, pero los identificadores varían; no usar ese número para operar en otra BD.$texto$,1,DATE '2026-10-16','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CUENTA_FINANCIERA_ADMINISTRAR','CUENTA_FINANCIERA_LEER','MOVIMIENTO_FINANCIERO_LEER','CORTE_CAJA_LEER','CORTE_CAJA_ADMINISTRAR']) WHERE g.slug='corte-caja-sobrante-1';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('corte-caja-sobrante-1',1,$texto$Preparar una caja de prueba independiente$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Entra con un usuario administrativo persistido a Administración → Finanzas → Cuentas financieras y busca CAJA-SOBRANTE-TEST. Si corresponde al caso ya concluido, sólo consulta y salta las capturas. 2. Para un ensayo nuevo pulsa Nuevo registro; selecciona institución y plantel disponibles, Código y Nombre CAJA-SOBRANTE-TEST, Tipo Caja, Moneda MXN, Saldo inicial1150.00, fecha de saldo inicial real y cuenta activa. Si el código ya pertenece a otra prueba, usa uno distinto y consérvalo en todo el recorrido. 3. Guarda y comprueba Saldo actual $1,150.00; no registres otro ingreso1150 ni reproduzcas los movimientos200/50 de la otra caja. 4. En Movimientos financieros → Cortes de caja filtra esta cuenta y comprueba que no exista otro corte abierto; si ya lo abriste para este mismo ensayo, continúa en él.$texto$,$texto$Caja nueva: saldo inicial y actual $1,150.00.$texto$,$texto$Cuenta aislada sin movimientos ni duplicación de pruebas anteriores.$texto$,$texto$En esta computadora no estaba la caja anterior CAJA-CORTE-TEST; se preparó otra. No modificar el saldo inicial de una caja existente para forzar este ejemplo ni usar dinero real.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('corte-caja-sobrante-1',2,$texto$Seleccionar la caja y abrir el corte$texto$,$texto$Administración$texto$,$texto$Movimientos financieros → Cortes de caja → Abrir corte$texto$,$texto$1. Entra a Administración → Finanzas → Movimientos financieros → Cortes de caja → Abrir corte. Selecciona la institución antes de enfocar Cuenta tipo caja; el autocompletado ofrece hasta diez cajas activas autorizadas y permite buscar desde tres caracteres, por ejemplo SOBRANTE. Selecciona la opción, no sólo escribas su nombre. 2. Captura Observaciones de apertura: Prueba de sobrante de 1 peso: saldo inicial1150, sin movimientos nuevos y conteo declarado1151. Pulsa Abrir corte y revisa institución, caja y observaciones en el modal. 3. Pulsa Confirmar y abrir corte una sola vez y anota su número. En Resumen comprueba Estado ABIERTO y Saldo inicial del sistema $1,150.00; en Apertura revisa fecha, responsable y observaciones. 4. No registres ingresos ni egresos después de abrir; continúa en Conteo y cierre o usa Ir a conteo y cierre desde Resumen.$texto$,$texto$Nuevo corte abierto con saldo inicial del sistema $1,150.00.$texto$,$texto$Apertura registrada con responsable y caja correcta.$texto$,$texto$El acceso de recuperación puede mostrar un aviso y no permite abrir cortes. Cierra sesión e ingresa con un administrador autorizado; no amplíes permisos para eludir el control. Cancelar en el modal no abre y Cancelar del formulario vuelve al historial.$texto$,$texto$/admin/cortes-caja/nuevo$texto$),
('corte-caja-sobrante-1',3,$texto$Intentar cerrar con $1,151 sin justificación$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conteo y cierre$texto$,$texto$1. En el detalle del corte abierto entra a Conteo y cierre. Si vienes del historial, filtra la caja y Estado ABIERTO, pulsa Contar y cerrar y abre esa pestaña. 2. Captura Efectivo declarado1151.00 y deja Justificación de diferencia vacía para comprobar el bloqueo de negocio. 3. En Observaciones de cierre escribe Prueba de cierre con sobrante de 1 peso. Pulsa Conciliar y cerrar y revisa el modal: caja, declarado $1,151 y justificación vacía. 4. Pulsa Confirmar y cerrar caja una sola vez. No captures un ingreso1 ni modifiques la cuenta para que coincida con el conteo.$texto$,$texto$Declarado $1,151.00 sin motivo para explicar la diferencia.$texto$,$texto$Intento deliberado de cierre sin justificar.$texto$,$texto$El conteo es ciego: saldo esperado y diferencia no se revelan antes de procesar. En operación captura la explicación real; omitirla aquí es sólo una prueba de validación.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sobrante-1',4,$texto$Comprobar que el cierre fue rechazado$texto$,$texto$Administración$texto$,$texto$Detalle abierto → Validación$texto$,$texto$1. Comprueba No se pudo cerrar el corte y Explica la diferencia entre el efectivo declarado y el saldo esperado. No debe indicar cierre exitoso. 2. La pestaña Conteo y cierre debe permitir corregir el mismo formulario; conserva el declarado1151 y las observaciones. 3. Consulta Resumen para comprobar Estado ABIERTO y regresa a Conteo y cierre sin recargar si deseas conservar la captura no guardada. 4. Continúa en el mismo corte: el propietario confirmó que no pudo cerrar sin justificación. No abras otra caja ni otro corte para corregir el mensaje.$texto$,$texto$Diferencia sin justificar → rechazo; corte permanece abierto.$texto$,$texto$Justificación obligatoria comprobada.$texto$,$texto$No alterar declarado1151 a1150 para evitar documentar el sobrante. El intento rechazado no registra un ingreso ni cambia el saldo de cuenta.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sobrante-1',5,$texto$Justificar y confirmar el cierre$texto$,$texto$Administración$texto$,$texto$Detalle del corte → Conteo y cierre → Confirmación$texto$,$texto$1. En Conteo y cierre del mismo corte conserva Efectivo declarado1151.00 y Observaciones de cierre: Prueba de cierre con sobrante de 1 peso. 2. Captura Justificación de diferencia: Prueba controlada: el conteo declarado supera en 1 peso el saldo del sistema, sin movimientos nuevos. 3. Pulsa Conciliar y cerrar y revisa número del corte, caja, declarado $1,151, justificación y observaciones. Como control adicional recomendado puedes Cancelar dentro del modal para revisar sin enviar y luego reabrirlo. 4. Cuando coincida, pulsa Confirmar y cerrar caja una sola vez. Debe permitir el cierre; el propietario confirmó que después de justificar pudo cerrar.$texto$,$texto$Mismo conteo $1,151.00, ahora justificado.$texto$,$texto$Corte cerrado con explicación trazable.$texto$,$texto$Cerrar después sólo vuelve al historial; no cierra el corte ni promete conservar campos sin guardar. No repetir la confirmación en un corte ya cerrado.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sobrante-1',6,$texto$Revisar el sobrante y cero movimientos$texto$,$texto$Administración$texto$,$texto$Detalle cerrado → Resumen / Apertura / Cierre y conciliación$texto$,$texto$1. En Resumen verifica Estado CERRADO, Saldo esperado al cierre $1,150.00, Efectivo declarado $1,151.00 y Diferencia del conteo $1.00 con explicación Sobrante. 2. En Apertura comprueba Saldo inicial del sistema $1,150.00 y las observaciones de este ensayo independiente. 3. En Cierre y conciliación revisa fecha, usuario, Movimientos incluidos0, Ingresos del corte $0.00 y Egresos del corte $0.00; debe indicar Sin movimientos registrados durante este corte. 4. En esa pestaña consulta Justificación de la diferencia y Observaciones de cierre; deben conservar la explicación y el registro original sin ofrecer otro formulario para modificar el corte cerrado.$texto$,$texto$Diferencia = $1,151 - $1,150 = +$1.00; movimientos0.$texto$,$texto$Sobrante documentado con fecha, responsable y justificación.$texto$,$texto$La diferencia positiva no es un movimiento financiero ni representa que el saldo contable se haya incrementado. No inventar un rango de folios cuando no hubo movimientos.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sobrante-1',7,$texto$Consultar historial sin volver a cerrar$texto$,$texto$Administración$texto$,$texto$Cortes de caja → Historial de conciliaciones$texto$,$texto$1. Pulsa Volver al historial al pie del detalle; filtra institución, Caja CAJA-SOBRANTE-TEST y Estado CERRADO → Aplicar filtros. Usa Desde/Hasta por fecha de apertura si hace falta. 2. Identifica el número del ensayo y consulta Saldo inicial $1,150.00, Diferencia del cierre $1.00 y Esperado $1,150.00. No confundir esta caja con la del faltante de la otra computadora. 3. Pulsa Ver detalle para comprobar las pestañas y Ver movimientos de la caja para consultar la cuenta; estos enlaces no registran operaciones. 4. Como control adicional recomendado, exporta Excel desde el historial con los mismos filtros y contrasta sus cifras; no se atribuye esta exportación como una nueva aceptación humana ya confirmada.$texto$,$texto$Corte cerrado conservado con diferencia positiva $1.00.$texto$,$texto$Consulta histórica sin duplicar apertura ni cierre.$texto$,$texto$No existe PDF específico de corte de caja. Los reportes financieros tienen su propio proceso de pantalla, Excel y PDF, todavía pendiente de prueba humana.$texto$,$texto$/admin/cortes-caja$texto$),
('corte-caja-sobrante-1',8,$texto$Verificar que la cuenta conserve $1,150$texto$,$texto$Administración$texto$,$texto$Cuentas financieras y siguiente prueba$texto$,$texto$1. Entra a Administración → Finanzas → Cuentas financieras, busca CAJA-SOBRANTE-TEST y pulsa Aplicar filtros; consulta Saldo actual, no sólo Saldo inicial. 2. Debe permanecer $1,150.00, sin ingreso automático de $1. El propietario confirmó ese saldo después del cierre; en esta caja nueva también el saldo inicial original es1150, a diferencia del ejemplo anterior que comenzaba en1000. 3. Si revisas Movimientos financieros de esta cuenta, no debe existir un ingreso1 generado por cerrar. No registres un movimiento manual ni cambies el saldo inicial para forzar1151. 4. Caso concluido: rechazo sin motivo, cierre con justificación, diferencia+1 y cuenta1150. Conserva el corte sin repetirlo. Siguiente prueba propuesta: reportes financieros de esta misma cuenta en pantalla, Excel y PDF, empezando por su estado mensual sin movimientos.$texto$,$texto$Cuenta $1,150.00; corte declarado $1,151.00; diferencia +$1.00.$texto$,$texto$Sobrante confirmado sin ajuste automático de saldos.$texto$,$texto$La investigación y tratamiento de sobrantes reales requiere el procedimiento autorizado por la escuela. Este ensayo no prescribe una regularización contable ni confirma todavía los reportes financieros.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;

-- Sustituir referencias de pendientes sólo mediante migración nueva.
UPDATE guia_proceso_paso SET instrucciones=replace(instrucciones,
 $texto$Siguiente propuesta aún pendiente: sobrante de $1 y luego reportes financieros de pantalla, Excel y PDF.$texto$,
 $texto$El sobrante de $1 ya tiene su propia guía confirmada; siguen pendientes los reportes financieros de pantalla, Excel y PDF.$texto$),
 precaucion=$texto$No repetir el corte ni registrar egresos automáticos. Faltante y sobrante justificados tienen guías confirmadas independientes; los reportes financieros siguen pendientes. El tratamiento de diferencias reales requiere autorización y revisión de la escuela.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='corte-caja-faltante-1') AND numero=8;
UPDATE guia_proceso_paso SET instrucciones=replace(instrucciones,
 $texto$el sobrante y los reportes financieros siguen pendientes.$texto$,
 $texto$el sobrante tiene su guía confirmada independiente y sólo los reportes financieros siguen pendientes de esta ronda.$texto$),
 precaucion=$texto$No confundir cierre de caja con cierre mensual. Cierre sin diferencia, faltante y sobrante justificados tienen sus guías confirmadas; reportes, transferencias, retiros y compras no quedan confirmados por este ejemplo.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='corte-caja-sin-diferencia') AND numero=10;
UPDATE guia_proceso_paso SET precaucion=$texto$No repetir los ensayos de seguridad ni cortes terminados. Cierre sin diferencia, faltante y sobrante de $1 justificados tienen guías confirmadas independientes. Siguiente prueba propuesta: reportes financieros de pantalla, Excel y PDF.$texto$
WHERE guia_id=(SELECT id FROM guia_proceso WHERE slug='seguridad-registro-validacion-pagos') AND numero=12;
UPDATE guia_proceso SET version_contenido=version_contenido+1,revisada_el=DATE '2026-10-16'
WHERE slug IN ('corte-caja-faltante-1','corte-caja-sin-diferencia','seguridad-registro-validacion-pagos');
